   "orig": "写到这里，我忍不住要把它与布兰登·卡特的另一个观察作个比较：那是在另一语境下，却与刚才的论证有显著的相似之处，尽管它从未被当作任何东西的推导提出。我们记得，一个定态的无电荷黑洞由两个克尔参数 m 与 a 描写，m 是黑洞质量，am 是它的角动量（为方便，取 c = G = 1 的单位，如普朗克单位，见 27.10 节）。埃兹拉·T·纽曼找到的克尔度规的一个推广（通常称为克尔—纽曼度规）代表带电的旋转定态黑洞。现在有三个参数：m、a、e。质量与角动量如前，此外还有总电荷 e。还有一个磁矩 M = ae，方向与角动量一致。卡特注意到：黑洞的磁旋比（质量的二倍乘磁矩，除以电荷乘角动量，对带电黑洞即 2m·ae/(e·am) = 2）对黑洞而言完全固定（与 m、a、e 无关），而且恰好取狄拉克当初为电子预言的值，即 2（对狄拉克电子，角动量 ½ħ，磁矩 ½ħe/mc，同样给出磁旋比 2，取 c = 1）。见 24.7 节。纽曼（2001）为这个巧合提供了一种解释：空间中沿复方向的一个位移。我们能把这一论证当作电子磁旋比的推导吗——独立于狄拉克原论证的那种？当然不能，按推导一词的任何通常含义都不能。它只有在电子能在某种意义上被视为黑洞时才可能适用。事实上，电子情形下 a、m、e 的实际值严重违反不等式 m² ≥ a² + e²，而这个不等式是相应的克尔—纽曼度规能代表黑洞的必要条件。所以，这个论证离狄拉克电子磁旋比的实际推导还差得很远。然而，它在揭示这个数值（经由向复数的延拓）的某种自然性上，与吉本斯—佩里关于黑洞温度的论证颇有几分相似。吉本斯—佩里论证确有一个额外优点：它并不局限于史瓦西/克尔族的时空度规。尽管如此，在我看来，这几乎不足以替它被普遍接受为实际推导作辩护。",
