   "orig": "我现在要提的问题是：两个肿块位置的量子叠加是定态吗？在常规量子力学里，只要我们认为每个肿块位置各自代表一个定态，且两种情形的能量相同（被移位的肿块既未升高也未降低），答案当然是肯定的。这只是第 21 章所学规则（另见 24.3 节）的初等应用。用态 |ψ⟩ 代表肿块原位置，|φ⟩ 代表移位后的位置，就有两个薛定谔方程分别描写两处的定态性：iħ∂|ψ⟩/∂t = E|ψ⟩，iħ∂|φ⟩/∂t = E|φ⟩，各自给出能量本征值为 E 的能量本征态。若叠加写成 |Φ⟩ = ψ|ψ⟩ + z|φ⟩，我们直接得到 iħ∂|Φ⟩/∂t = E|Φ⟩，无论（常）振幅 ψ 与 z 取什么值。于是每一个量子叠加 |Φ⟩ 也是定态。如果 |ψ⟩ 与 |φ⟩ 各自能永远待在那里，它们的每一个量子叠加 |Φ⟩ 也能。这不过是标准量子力学的预期。",
