   "orig": "把这两个 Killing 矢量不同这件事讲得更透一些，是重要的。我说 k_ψ 与 k_φ 不同，是在很深的意义上说的：它们实际上是不同时空上的矢量场！有人也许试图这样看：这两个时空的差别只在于度规结构略有不同。于是我们可以试着把它们想成真正同一个空间，只是指定了略微不同的度规张量场，比如 g_ψ 与 g_φ。但采取这个立场，就与爱因斯坦理论的一条非常基本的原则——广义协变原理（19.6 节）——分道扬镳了。把两个时空的点集在某种意义上视为相同的点集，实际上就是在两个时空之间规定一种逐点的认同；那等于把一个时空中的点，与另一时空中坐标标签相同的点等同起来。而广义协变原理否认特定坐标系有任何意义。的确，它断言：在两个不同的时空之间，不存在任何优先的逐点认同。我们需要能写下薛定谔方程。可没有一个唯一的 k，怎么写？最直接的建议或许是试着把 k_ψ 与 k_φ 认同起来，但那样做肯定违反爱因斯坦理论的一条基本原理，因为这意味着我们认为这两个 Killing 矢量栖居于同一个空间——那是作弊！在我看来，在这种情形下，我们确实开始目睹量子力学基本原理与广义相对论基本原理之间的一场冲突了。",
