   "orig": "事实上，人们也许考虑采用第二种能量度量（即引力相互作用能）作为 E_G 的另一种定义。以引力自能表述的第一种提议，在我看来根据更足；但在目前的理解阶段，不应排除其他可能。迪奥西（1989）考虑过上述两种提议，用于与我下面要给出的目的类似的目的，但他还提出了一种（随机）动力学，这一点我不打算跟进。这几种不同的建议（以及另一些）应当可以在即将谈到的那类实验中被区分开。不过应当强调：即使是最有根据的这些提议，其动机也不完全，并非全无争议。那么，拿这个根本性的能量不确定性 E_G 怎么办？下一步是援引海森堡不确定性原理的一种形式（时间/能量不确定关系，见 21.11 节）。研究不稳定粒子或不稳定原子核（如铀 U²³⁸）时，有个熟悉的事实：平均寿命 T 自带时间不确定性，它与一个能量不确定性互为倒数，后者由 ħ/2T 给出。例如，21.11 节曾指出，U²³⁸ 核的寿命约 10⁹ 年，所以每个核有一个约 10⁻⁵¹ 焦耳的根本性能量不确定性；经爱因斯坦的 E = mc² 换算，这相当于其总质量约 10⁻⁴⁴ 的质量不确定性。现在，我们把叠加态 |Φ⟩ = ψ|ψ⟩ + z|φ⟩ 想成类似的东西：它自身不稳定，有一个寿命 T_G，按海森堡公式与上述根本性能量不确定性 E_G 相联系。按这幅图像，任何像 |Φ⟩ 这样的叠加都将在平均时标 T_G ≈ ħ/E_G 内衰变为其两个组元态 |ψ⟩ 或 |φ⟩ 之一。",
