   "orig": "上述 FELIX 提议在技术上极其困难，原因有好几个。一个主要问题是：要在相距约 10 000 km 的太空平台之间瞄准 X 射线光子，精度要求极高。无论如何，太空实验本质上困难且极其昂贵；如果有可行的地基替代方案，那会带来许多好处。所幸，这样的替代方案看来确实有实际可能。由于威廉·马歇尔的一个巧妙建议，以及迪克·布莫斯特与克里斯托夫·西蒙为实施它想出的同样聪明的点子，一个可行的地基替代方案看来确已提上日程，目前正在积极研究。该提议是：不用单个 X 射线光子的冲击来产生所需的小镜子移动，而用一颗能量低得多的光子（比如可见光甚至红外光子），让它来回反射约 10⁶ 次；于是同一颗光子对小镜子有 10⁶ 次冲击，顶替先前提议的单次 X 射线冲击；见图 30.26。撰写这些内容时，这类初步实验在一两年内进行，似乎没有根本性障碍。如果成功进行，这个初步实验离引力 OR 的决定性检验所要求的，可能仍差五六个数量级。然而，如果两个小镜子位置叠加的量子相干性能够维持住，这将意味着（按质量计）比目前的薛定谔猫纪录（C⁷⁰ 富勒烯分子）前进约 10¹² 倍。看来很可能：一旦这一阶段成功到达——极简引力 OR 方案（30.9–30.12 节）在此阶段预言与标准量子力学一致——那么检验引力 OR 新预言所需的额外改进，也很可能在再过几年之内到位。",
